INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_07','V209','Nguyễn Minh',7,'辛苦您了，谢谢！','xīn kǔ nín le， xiè xiè！','Chị vất vả rồi, em cảm ơn ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT210','S6','Đổi tiền và hỏi tỷ giá','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V210','SIT210','P1','twist','ban_chinh_thuc','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','机场外币兑换汇率略低于市区银行，适合小额应急兑换，大额兑换建议去正规银行；往返双向兑换会产生双重汇兑损耗，尽量按需兑换。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_01','V210','阮明',1,'您好，我刚落地机场，想把随身带的越南盾兑换成人民币。','nín hǎo， wǒ gāng luò dì jī chǎng， xiǎng bǎ suí shēn dài de yuè nán dùn duì huàn chéng rén mín bì。','Chào chị, tôi vừa xuống sân bay, muốn đổi số tiền Việt Nam đồng mang theo sang nhân dân tệ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_02','V210','职员',2,'您好，先跟您确认一下，您清楚机场兑换点和市区银行汇率有差别吗？','nín hǎo， xiān gēn nín què rèn yī xià， nín qīng chǔ jī chǎng duì huàn diǎn hé shì qū yín háng huì lǜ yǒu chā bié ma？','Chào anh, để tôi xác nhận trước với anh, anh có biết tỷ giá ở quầy đổi tiền sân bay khác với ngân hàng trong thành phố không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_03','V210','阮明',3,'之前听同学提过一句，但具体差多少我不太了解啊。','zhī qián tīng tóng xué tí guò yī jù， dàn jù tǐ chà duō shǎo wǒ bù tài liǎo jiě a。','Trước đó có nghe bạn học nhắc qua một câu, nhưng cụ thể chênh lệch bao nhiêu thì tôi không rõ lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_04','V210','职员',4,'今日实时汇率牌价就在柜台上方，机场汇率会比市区银行低三个点哦。','jīn rì shí shí huì lǜ pái jià jiù zài guì tái shàng fāng， jī chǎng huì lǜ huì bǐ shì qū yín háng dī sān gè diǎn ó。','Bảng tỷ giá thời gian thực hôm nay ở ngay phía trên quầy, tỷ giá ở sân bay sẽ thấp hơn ngân hàng trong thành phố khoảng ba điểm đó ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_05','V210','阮明',5,'这样啊，差价还挺明显，那我先兑换一千元人民币应急可以吗？','zhè yàng a， chā jià hái tǐng míng xiǎn， nà wǒ xiān duì huàn yī qiān yuán rén mín bì yìng jí kě yǐ ma？','Vậy à, chênh lệch cũng khá rõ đấy, vậy tôi đổi tạm một nghìn tệ để dùng gấp được không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_06','V210','职员',6,'兑换外币有流程要求，需要出示护照登记个人信息哈。','duì huàn wài bì yǒu liú chéng yāo qiú， xū yào chū shì hù zhào dēng jì gè rén xìn xī hā。','Đổi ngoại tệ có quy trình yêu cầu, cần xuất trình hộ chiếu để đăng ký thông tin cá nhân ạ.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_07','V210','阮明',7,'没问题，护照我一直随身带着，现在递给您。那手续费是单独收取的吗？','méi wèn tí， hù zhào wǒ yì zhí suí shēn dài zhe， xiàn zài dì gěi nín。 nà shǒu xù fèi shì dān dú shōu qǔ de ma？','Không vấn đề gì, hộ chiếu tôi luôn mang theo bên mình, đưa cho chị đây. Vậy phí dịch vụ có tính riêng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_08','V210','职员',8,'单笔一千元以内的小额兑换免手续费，系统已经直接帮您核算完毕。','dān bǐ yī qiān yuán yǐ nèi de xiǎo é duì huàn miǎn shǒu xù fèi， xì tǒng yǐ jīng zhí jiē bāng nín hé suàn wán bì。','Giao dịch nhỏ dưới một nghìn tệ thì được miễn phí dịch vụ, hệ thống đã tính toán giúp anh xong rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_09','V210','阮明',9,'我再多问一句，如果剩下没花完的人民币，还能在这里换回越南盾吗？','wǒ zài duō wèn yī jù， rú guǒ shèng xià méi huā wán de rén mín bì， hái néng zài zhè lǐ huàn huí yuè nán dùn ma？','Tôi hỏi thêm một câu nữa, nếu còn dư nhân dân tệ chưa tiêu hết thì có thể đổi lại thành tiền Việt ở đây không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_10','V210','职员',10,'可以兑换返程外币，但二次兑换会再收取一笔汇兑差价，不太划算。','kě yǐ duì huàn fǎn chéng wài bì， dàn èr cì duì huàn huì zài shōu qǔ yī bǐ huì duì chā jià， bù tài huá suàn。','Có thể đổi ngoại tệ khi về, nhưng đổi lần hai sẽ tính thêm một khoản chênh lệch tỷ giá nữa, không có lợi lắm đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_11','V210','阮明',11,'明白了，那我就只换一千元，够用今天打车吃饭就行。','míng bái le， nà wǒ jiù zhǐ huàn yī qiān yuán， gòu yòng jīn tiān dǎ chē chī fàn jiù xíng。','Tôi hiểu rồi, vậy tôi chỉ đổi một nghìn tệ thôi, đủ dùng đi taxi ăn uống hôm nay là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_12','V210','职员',12,'好，我现在按实时汇率帮您清点现金，稍等片刻。','hǎo， wǒ xiàn zài àn shí shí huì lǜ bāng nín qīng diǎn xiàn jīn， shāo děng piàn kè。','Vâng, giờ tôi tính tiền mặt theo tỷ giá thời gian thực cho anh, anh chờ một chút nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_13','V210','阮明',13,'辛苦您了，汇率有变动也麻烦您再跟我说一声。','xīn kǔ nín le， huì lǜ yǒu biàn dòng yě má fán nín zài gēn wǒ shuō yī shēng。','Chị vất vả rồi, nếu tỷ giá có thay đổi thì phiền chị báo lại cho tôi một tiếng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_14','V210','职员',14,'刚刚已经核对过牌价，短时间不会波动，现金给您收好。','gāng gāng yǐ jīng hé duì guò pái jià， duǎn shí jiān bú huì bō dòng， xiàn jīn gěi nín shōu hǎo。','Tôi vừa kiểm tra lại bảng giá rồi, trong thời gian ngắn sẽ không biến động đâu, tiền mặt anh cầm cẩn thận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_15','V210','阮明',15,'太感谢您耐心讲解，省去我不少麻烦，那就兑换吧！','tài gǎn xiè nín nài xīn jiǎng jiě， shěng qù wǒ bù shǎo má fán， nà jiù duì huàn ba！','Cảm ơn chị đã kiên nhẫn giải thích, đỡ cho tôi bao nhiêu phiền phức, vậy thì đổi luôn nhé!','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT211','S5','Kết nối WiFi sân bay','Xin mật khẩu wifi, phải xác thực qua số điện thoại','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V211','SIT211','P1','suon_se','tuy_y','Xin mật khẩu wifi, phải xác thực qua số điện thoại',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_01','V211','Nguyễn Minh',1,'你好，请问机场的免费WiFi密码是多少呀？','nǐ hǎo， qǐng wèn jī chǎng de miǎn fèi WiFi mì mǎ shì duō shǎo ya？','Chào bạn, cho mình hỏi mật khẩu WiFi miễn phí ở sân bay là gì vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_02','V211','Nhân viên',2,'很简单的，密码是机场全称的首字母加八个八哦。','hěn jiǎn dān de， mì mǎ shì jī chǎng quán chēng de shǒu zì mǔ jiā bā gè bā ó。','Đơn giản lắm, mật khẩu là chữ cái đầu của tên đầy đủ sân bay cộng với tám số tám đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_03','V211','Nguyễn Minh',3,'我试了一下，怎么连不上呢？','wǒ shì le yī xià， zěn me lián bù shàng ne？','Mình thử rồi mà sao không kết nối được nhỉ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_04','V211','Nhân viên',4,'需要先打开浏览器验证一下，登录之后就能用啦。','xū yào xiān dǎ kāi liú lǎn qì yàn zhèng yī xià， dēng lù zhī hòu jiù néng yòng la。','Cần mở trình duyệt xác thực trước đã, đăng nhập xong là dùng được liền à.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_05','V211','Nguyễn Minh',5,'原来是这样，太感谢你啦！','yuán lái shì zhè yàng， tài gǎn xiè nǐ la！','Ra là vậy, cảm ơn bạn nhiều nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_06','V211','Nhân viên',6,'没事哒，有问题再问哈！','méi shì dá， yǒu wèn tí zài wèn hā！','Có gì đâu, có vấn đề gì cứ hỏi tiếp nha!','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT212','S1','Gọi người đón, báo vị trí','Báo cho bạn đến đón biết mình đã tới và đang ở đâu','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V212','SIT212','P1','suon_se','tuy_y','Báo cho bạn đến đón biết mình đã tới và đang ở đâu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_01','V212','Nguyễn Minh',1,'宇哥，我已经到机场啦，顺利入境了！','yǔ gē， wǒ yǐ jīng dào jī chǎng la， shùn lì rù jìng le！','Anh Vũ ơi, em đến sân bay rồi nè, nhập cảnh suôn sẻ luôn!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_02','V212','Đón (Trần Vũ)',2,'太好了！你现在在哪个位置呀？','tài hǎo le！ nǐ xiàn zài zài nǎ ge wèi zhì ya？','Tốt quá! Giờ em đang ở chỗ nào vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_03','V212','Nguyễn Minh',3,'我在国内到达出口的问询台旁边呢。','wǒ zài guó nèi dào dá chū kǒu de wèn xún tái páng biān ne。','Em đang ở gần quầy hỏi thông tin ở lối ra đến quốc nội nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_04','V212','Đón (Trần Vũ)',4,'好的，我马上就到，你就在原地等我别乱跑哈。','hǎo de， wǒ mǎ shàng jiù dào， nǐ jiù zài yuán dì děng wǒ bié luàn pǎo hā。','Được rồi, anh tới ngay đây, em cứ đứng nguyên chỗ đó chờ anh, đừng chạy lung tung nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_05','V212','Nguyễn Minh',5,'没问题，我就在这里等你，不着急的。','méi wèn tí， wǒ jiù zài zhè lǐ děng nǐ， bù zháo jí de。','Không sao đâu, em đứng đây chờ anh, không vội đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_06','V212','Đón (Trần Vũ)',6,'五分钟就到，一会儿见！','wǔ fēn zhōng jiù dào， yī huì er jiàn！','Năm phút nữa là tới, lát gặp nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT213','S1','Không thấy người đón, gọi xác nhận','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V213','SIT213','P1','twist','tuy_y','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_01','V213','Nguyễn Minh',1,'宇哥，我已经在出口等了十分钟了，没看到你呀。','yǔ gē， wǒ yǐ jīng zài chū kǒu děng le shí fēn zhōng le， méi kàn dào nǐ ya。','Anh Vũ ơi, em đứng chờ ở cửa ra mười phút rồi mà không thấy anh đâu cả.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_02','V213','Đón (Trần Vũ)',2,'哎呀抱歉！我走错出口了，我在二号出口，你在几号呀？','āi yā bào qiàn！ wǒ zǒu cuò chū kǒu le， wǒ zài èr hào chū kǒu， nǐ zài jǐ hào ya？','Ôi xin lỗi em! Anh đi lộn cửa rồi, anh đang ở cửa số 2, em ở cửa số mấy vậy?','AM10');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_03','V213','Nguyễn Minh',3,'我在一号出口，难怪看不到呢。','wǒ zài yī hào chū kǒu， nán guài kàn bú dào ne。','Em ở cửa số 1, thảo nào không thấy nhau.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_04','V213','Đón (Trần Vũ)',4,'太不好意思了！我马上走通道过来，两分钟就到你那边。','tài bù hǎo yì sī le！ wǒ mǎ shàng zǒu tōng dào guò lái， liǎng fēn zhōng jiù dào nǐ nà biān。','Ngại quá đi! Anh chạy qua lối đi ngay đây, hai phút nữa là tới chỗ em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_05','V213','Nguyễn Minh',5,'没事没事，不着急，我慢慢等你就好啦。','méi shì méi shì， bù zháo jí， wǒ màn màn děng nǐ jiù hǎo la。','Không sao không sao, đừng vội, em từ từ chờ anh là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_06','V213','Đón (Trần Vũ)',6,'辛苦你啦，马上汇合！','xīn kǔ nǐ la， mǎ shàng huì hé！','Em vất vả rồi, gặp nhau ngay đây!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT214','S2','Đặt xe công nghệ, xác nhận tài xế','Xác nhận đúng tài xế và biển số trước khi lên xe','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V214','SIT214','P1','suon_se','tuy_y','Xác nhận đúng tài xế và biển số trước khi lên xe',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_01','V214','Tài xế',1,'你好，是尾号3621的乘客吧？我到机场上车点了。','nǐ hǎo， shì wěi hào 3621 de chéng kè ba？ wǒ dào jī chǎng shàng chē diǎn le。','Chào bạn, khách đuôi số 3621 phải không? Mình đến điểm đón ở sân bay rồi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_02','V214','Nguyễn Minh',2,'对的是我！麻烦问一下，您的车牌号是多少呀？','duì de shì wǒ！ má fán wèn yī xià， nín de chē pái hào shì duō shǎo ya？','Đúng là em đây! Cho em hỏi, biển số xe của anh là gì vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_03','V214','Tài xế',3,'车牌是浙A8523K，黑色轿车，很好认的。','chē pái shì zhè A8523K， hēi sè jiào chē， hěn hǎo rèn de。','Biển số là Chiết A8523K, xe màu đen, dễ nhận lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_04','V214','Nguyễn Minh',4,'好的，我看到您的车了，马上走过去哈。','hǎo de， wǒ kàn dào nín de chē le， mǎ shàng zǒu guò qù hā。','Dạ, em thấy xe anh rồi, em đi qua ngay đây ạ.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_05','V214','Tài xế',5,'不急，慢慢走，注意身边行李就行。','bù jí， màn màn zǒu， zhù yì shēn biān xíng lǐ jiù xíng。','Không vội đâu, cứ từ từ, chú ý hành lý bên người là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_06','V214','Nguyễn Minh',6,'好嘞，辛苦您等我一下！','hǎo lei， xīn kǔ nín děng wǒ yī xià！','Dạ được, anh chờ em một chút nha!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT215','S2','Báo địa chỉ đến cho tài xế','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V215','SIT215','P1','suon_se','tuy_y','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_01','V215','Tài xế',1,'同学，我们现在出发，你去哪里呀？','tóng xué， wǒ men xiàn zài chū fā， nǐ qù nǎ lǐ ya？','Bạn ơi, giờ mình xuất phát nhé, bạn đi đâu vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_02','V215','Nguyễn Minh',2,'师傅您好，麻烦去省城理工大学留学生公寓。','shī fù nín hǎo， má fán qù shěng chéng lǐ gōng dà xué liú xué shēng gōng yù。','Chào anh tài xế, phiền anh chở em đến ký túc xá lưu học sinh trường Đại học Bách khoa Tỉnh thành ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_03','V215','Tài xế',3,'是新校区那个留学生宿舍吧？','shì xīn xiào qū nà ge liú xué shēng sù shè ba？','Là ký túc xá lưu học sinh ở khu cơ sở mới đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_04','V215','Nguyễn Minh',4,'对的！我第一次去，辛苦您多留意路线呢。','duì de！ wǒ dì yī cì qù， xīn kǔ nín duō liú yì lù xiàn ne。','Dạ đúng ạ! Đây là lần đầu em đến đó, phiền anh để ý đường giúp em nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_05','V215','Tài xế',5,'放心吧，这条路我常跑，不会走错的。','fàng xīn ba， zhè tiáo lù wǒ cháng pǎo， bú huì zǒu cuò de。','Yên tâm đi, tuyến đường này anh chạy suốt, không đi lộn đâu.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_06','V215','Nguyễn Minh',6,'那就太好了，谢谢您！','nà jiù tài hǎo le， xiè xiè nín！','Vậy thì tốt quá, cảm ơn anh!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT216','S2','Thanh toán quét mã sau khi đi taxi','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V216','SIT216','P1','twist','tuy_y','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_01','V216','Tài xế',1,'同学，我们到学校门口啦，车程结束了。','tóng xué， wǒ men dào xué xiào mén kǒu la， chē chéng jié shù le。','Bạn ơi, tới trước cổng trường rồi nè, chuyến đi kết thúc rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_02','V216','Nguyễn Minh',2,'好的！我想扫码支付，可是手机网络有点慢怎么办？','hǎo de！ wǒ xiǎng sǎo mǎ zhī fù， kě shì shǒu jī wǎng luò yǒu diǎn màn zěn me bàn？','Dạ! Em muốn quét mã thanh toán, nhưng mạng điện thoại hơi chậm, làm sao đây ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_03','V216','Tài xế',3,'没关系呀，不急，你慢慢加载就行。','méi guān xì ya， bù jí， nǐ màn màn jiā zài jiù xíng。','Không sao đâu, đừng vội, em cứ từ từ tải nhé.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_04','V216','Nguyễn Minh',4,'终于好了，已经支付成功啦，您看一下！','zhōng yú hǎo le， yǐ jīng zhī fù chéng gōng la， nín kàn yī xià！','Được rồi ạ, thanh toán thành công rồi nè, anh xem lại giúp em!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_05','V216','Tài xế',5,'收到了，没问题。路上辛苦了，欢迎下次坐车哈！','shōu dào le， méi wèn tí。 lù shàng xīn kǔ le， huān yíng xià cì zuò chē hā！','Nhận được rồi, không vấn đề gì. Đi đường vất vả rồi, lần sau lại đi xe nha!','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_06','V216','Nguyễn Minh',6,'谢谢师傅，再见！','xiè xiè shī fù， zài jiàn！','Cảm ơn anh tài xế, chào anh!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT217','S7','Nhận phòng ký túc xá','Xuất trình giấy tờ, nhận phòng và chìa khóa','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V217','SIT217','P1','suon_se','ban_chinh_thuc','Xuất trình giấy tờ, nhận phòng và chìa khóa',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_01','V217','Nguyễn Minh',1,'老师您好，我是新来的留学生，今天来办理宿舍入住。','lǎo shī nín hǎo， wǒ shì xīn lái de liú xué shēng， jīn tiān lái bàn lǐ sù shè rù zhù。','Chào thầy/cô, em là du học sinh mới đến, hôm nay em đến làm thủ tục nhận phòng ký túc xá ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_02','V217','Tiền sảnh',2,'好的，请出示你的护照和入学通知书哦。','hǎo de， qǐng chū shì nǐ de hù zhào hé rù xué tōng zhī shū ó。','Được rồi, em vui lòng đưa hộ chiếu và giấy báo nhập học cho tôi xem nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_03','V217','Nguyễn Minh',3,'好的，这是我的证件和录取文件，您看一下。','hǎo de， zhè shì wǒ de zhèng jiàn hé lù qǔ wén jiàn， nín kàn yī xià。','Vâng ạ, đây là giấy tờ và giấy báo trúng tuyển của em, thầy/cô xem giúp em với ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_04','V217','Tiền sảnh',4,'信息核对无误，这是你的宿舍钥匙和门禁卡。','xìn xī hé duì wú wù， zhè shì nǐ de sù shè yào shi hé mén jìn kǎ。','Thông tin đối chiếu không có sai sót gì, đây là chìa khóa phòng và thẻ ra vào của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_05','V217','Nguyễn Minh',5,'请问我的宿舍是几楼几号呀？','qǐng wèn wǒ de sù shè shì jǐ lóu jǐ hào ya？','Cho em hỏi phòng của em ở tầng mấy, số mấy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_06','V217','Tiền sảnh',6,'四楼408室，单人留学生宿舍，条件还不错呢。','sì lóu 408 shì， dān rén liú xué shēng sù shè， tiáo jiàn hái bú cuò ne。','Tầng 4 phòng 408, phòng đơn dành cho du học sinh, điều kiện khá tốt đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_07','V217','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn thầy/cô nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT218','S7','Ký hợp đồng ở ký túc xá','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V218','SIT218','P1','suon_se','ban_chinh_thuc','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_01','V218','Tiền sảnh',1,'这是留学生住宿合同，你仔细看一下条款哦。','zhè shì liú xué shēng zhù sù hé tóng， nǐ zǐ xì kàn yī xià tiáo kuǎn ó。','Đây là hợp đồng ở ký túc xá dành cho du học sinh, em xem kỹ các điều khoản nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_02','V218','Nguyễn Minh',2,'好的，请问主要是住宿规定和缴费事项吧？','hǎo de， qǐng wèn zhǔ yào shì zhù sù guī dìng hé jiǎo fèi shì xiàng ba？','Vâng ạ, chủ yếu là quy định về ở ký túc xá và các khoản phí phải nộp đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_03','V218','Tiền sảnh',3,'对的，还有作息时间、宿舍安全的相关要求呢。','duì de， hái yǒu zuò xī shí jiān、 sù shè ān quán de xiāng guān yāo qiú ne。','Đúng vậy, còn có cả giờ giấc sinh hoạt và các yêu cầu về an toàn trong ký túc xá nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_04','V218','Nguyễn Minh',4,'我看完了，没有疑问，可以签字了吗？','wǒ kàn wán le， méi yǒu yí wèn， kě yǐ qiān zì le ma？','Em xem xong rồi, không có thắc mắc gì, giờ em ký được chưa ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_05','V218','Tiền sảnh',5,'可以的，在这里签上你的中文或英文姓名就行。','kě yǐ de， zài zhè lǐ qiān shàng nǐ de zhōng wén huò yīng wén xìng míng jiù xíng。','Được rồi, em ký tên bằng tiếng Trung hoặc tiếng Anh vào đây là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_06','V218','Nguyễn Minh',6,'好的，我签好了，交给您。','hǎo de， wǒ qiān hǎo le， jiāo gěi nín。','Vâng ạ, em ký xong rồi, gửi lại thầy/cô đây ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_07','V218','Tiền sảnh',7,'手续办完，祝你入住愉快！','shǒu xù bàn wán， zhù nǐ rù zhù yú kuài！','Xong thủ tục rồi, chúc em ở vui vẻ nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT219','S7','Hỏi WiFi, phòng giặt, giờ đóng cửa ký túc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V219','SIT219','P1','suon_se','ban_chinh_thuc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_01','V219','Nguyễn Minh',1,'老师您好，我想咨询几个宿舍的相关问题可以吗？','lǎo shī nín hǎo， wǒ xiǎng zī xún jǐ gè sù shè de xiāng guān wèn tí kě yǐ ma？','Chào thầy/cô, em muốn hỏi vài vấn đề liên quan đến ký túc xá được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_02','V219','Tiền sảnh',2,'当然可以，你尽管问哈。','dāng rán kě yǐ， nǐ jǐn guǎn wèn hā。','Được chứ, em cứ hỏi thoải mái nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_03','V219','Nguyễn Minh',3,'请问宿舍WiFi密码是多少？洗衣房在哪个位置啊？','qǐng wèn sù shè WiFi mì mǎ shì duō shǎo？ xǐ yī fáng zài nǎ ge wèi zhì a？','Cho em hỏi mật khẩu WiFi ở ký túc xá là gì ạ? Phòng giặt ở đâu vậy ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_04','V219','Tiền sảnh',4,'WiFi密码贴在房门背后，洗衣房在二楼楼梯口呢。','WiFi mì mǎ tiē zài fáng mén bèi hòu， xǐ yī fáng zài èr lóu lóu tī kǒu ne。','Mật khẩu WiFi dán ở mặt sau cửa phòng, phòng giặt ở đầu cầu thang tầng hai đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_05','V219','Nguyễn Minh',5,'那宿舍门禁的开关时间是几点呀？','nà sù shè mén jìn de kāi guān shí jiān shì jǐ diǎn ya？','Vậy giờ mở đóng cửa ký túc xá là mấy giờ ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_06','V219','Tiền sảnh',6,'早上六点开门，晚上十一点关门，记得按时回寝哦。','zǎo shàng liù diǎn kāi mén， wǎn shàng shí yì diǎn guān mén， jì de àn shí huí qǐn ó。','Sáng 6 giờ mở cửa, tối 11 giờ đóng cửa, nhớ về phòng đúng giờ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_07','V219','Nguyễn Minh',7,'好的，我都记住了，谢谢您！','hǎo de， wǒ dōu jì zhù le， xiè xiè nín！','Vâng ạ, em nhớ hết rồi, cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT220','S7','Báo hỏng đèn phòng','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V220','SIT220','P1','that_bai_nhe','tuy_y','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_01','V220','Nguyễn Minh',1,'阿姨您好，我是408宿舍的同学，房间的顶灯不亮了。','ā yí nín hǎo， wǒ shì 408 sù shè de tóng xué， fáng jiān de dǐng dēng bù liàng le。','Cô ơi, cháu là sinh viên phòng 408, đèn trần trong phòng bị hỏng rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_02','V220','Quản lý',2,'是完全不亮，还是一闪一闪的呀？','shì wán quán bù liàng， hái shì yī shǎn yī shǎn de ya？','Là tắt hẳn luôn hay chỉ nhấp nháy vậy con?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_03','V220','Nguyễn Minh',3,'完全打不开，应该是坏掉了呢。','wán quán dǎ bù kāi， yīng gāi shì huài diào le ne。','Tắt hẳn luôn ạ, chắc là hỏng rồi cô.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_04','V220','Quản lý',4,'好的，我帮你登记报修，维修师傅明天上午过来修哈。','hǎo de， wǒ bāng nǐ dēng jì bào xiū， wéi xiū shī fù míng tiān shàng wǔ guò lái xiū hā。','Được rồi, cô giúp con đăng ký sửa, thợ sẽ đến sửa vào sáng mai nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_05','V220','Nguyễn Minh',5,'好的，今晚只能先开台灯了，麻烦阿姨啦！','hǎo de， jīn wǎn zhǐ néng xiān kāi tái dēng le， má fán ā yí la！','Dạ vâng, tối nay đành phải bật đèn bàn tạm vậy, phiền cô quá!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_06','V220','Quản lý',6,'没事的，小事而已，明天肯定修好。','méi shì de， xiǎo shì ér yǐ， míng tiān kěn dìng xiū hǎo。','Không sao đâu, chuyện nhỏ thôi mà, mai chắc chắn sửa xong.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT221','S6','Mở tài khoản ngân hàng, lấy số','Lấy số thứ tự và điền đơn mở tài khoản','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V221','SIT221','P1','suon_se','chinh_thuc','Lấy số thứ tự và điền đơn mở tài khoản',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_01','V221','Nguyễn Minh',1,'您好，我想办理银行卡开户业务，请问怎么操作？','nín hǎo， wǒ xiǎng bàn lǐ yín háng kǎ kāi hù yè wù， qǐng wèn zěn me cāo zuò？','Chào anh/chị, tôi muốn làm thủ tục mở thẻ ngân hàng, xin hỏi phải làm như thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_02','V221','Quản lý sảnh',2,'您好，先在取号机取个排队号，再填写这份开户申请表哦。','nín hǎo， xiān zài qǔ hào jī qǔ gè pái duì hào， zài tián xiě zhè fèn kāi hù shēn qǐng biǎo ó。','Chào anh/chị, trước tiên xin lấy số thứ tự ở máy lấy số, sau đó điền vào mẫu đơn đăng ký mở tài khoản này ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_03','V221','Nguyễn Minh',3,'好的，表格上的信息我都如实填写就可以吧？','hǎo de， biǎo gé shàng de xìn xī wǒ dōu rú shí tián xiě jiù kě yǐ ba？','Vâng, thông tin trên mẫu đơn tôi điền đúng sự thật là được phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_04','V221','Quản lý sảnh',4,'对的，姓名、证件信息、住址全部填完整就行。','duì de， xìng míng、 zhèng jiàn xìn xī、 zhù zhǐ quán bù tián wán zhěng jiù xíng。','Đúng vậy, anh/chị chỉ cần điền đầy đủ họ tên, thông tin giấy tờ và địa chỉ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_05','V221','Nguyễn Minh',5,'表格填好了，号也取到了，接下来等待叫号吗？','biǎo gé tián hǎo le， hào yě qǔ dào le， jiē xià lái děng dài jiào hào ma？','Tôi điền xong mẫu đơn rồi, cũng đã lấy số rồi, tiếp theo là chờ gọi số phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_06','V221','Quản lý sảnh',6,'是的，轮到你的时候直接去柜台办理即可。','shì de， lún dào nǐ de shí hòu zhí jiē qù guì tái bàn lǐ jí kě。','Đúng vậy, đến lượt anh/chị thì cứ ra quầy làm thủ tục là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_07','V221','Nguyễn Minh',7,'好的，谢谢您的指导！','hǎo de， xiè xiè nín de zhǐ dǎo！','Vâng, cảm ơn anh/chị đã hướng dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT222','S6','Xuất trình giấy tờ mở thẻ ngân hàng','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V222','SIT222','P1','twist','chinh_thuc','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_01','V222','Nhân viên',1,'您好，请问办理什么业务？','nín hǎo， qǐng wèn bàn lǐ shén me yè wù？','Chào anh/chị, xin hỏi anh/chị cần làm thủ tục gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_02','V222','Nguyễn Minh',2,'您好，我是留学生，想办理储蓄卡开户。','nín hǎo， wǒ shì liú xué shēng， xiǎng bàn lǐ chǔ xù kǎ kāi hù。','Chào anh/chị, tôi là du học sinh, muốn làm thủ tục mở thẻ tiết kiệm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_03','V222','Nhân viên',3,'麻烦出示你的护照、签证和学校在读证明哦。','má fán chū shì nǐ de hù zhào、 qiān zhèng hé xué xiào zài dú zhèng míng ó。','Phiền anh/chị xuất trình hộ chiếu, thị thực và giấy xác nhận đang học tại trường ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_04','V222','Nguyễn Minh',4,'证件都在这里，在读证明我打印的黑白版可以吗？','zhèng jiàn dōu zài zhè lǐ， zài dú zhèng míng wǒ dǎ yìn de hēi bái bǎn kě yǐ ma？','Giấy tờ đều ở đây cả, giấy xác nhận đang học tôi in bản đen trắng có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_05','V222','Nhân viên',5,'可以的，黑白有效，我帮你录入系统信息。','kě yǐ de， hēi bái yǒu xiào， wǒ bāng nǐ lù rù xì tǒng xìn xī。','Được ạ, bản đen trắng vẫn có giá trị, tôi sẽ nhập thông tin vào hệ thống cho anh/chị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_06','V222','Nguyễn Minh',6,'好的，辛苦您了！大概多久能办好呀？','hǎo de， xīn kǔ nín le！ dà gài duō jiǔ néng bàn hǎo ya？','Vâng, cảm ơn anh/chị đã vất vả! Khoảng bao lâu thì xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_07','V222','Nhân viên',7,'很快的，三分钟就能完成开卡流程。','hěn kuài de， sān fēn zhōng jiù néng wán chéng kāi kǎ liú chéng。','Nhanh thôi ạ, chỉ ba phút là hoàn tất thủ tục mở thẻ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT223','S6','Kích hoạt thẻ ngân hàng mới','Đổi mật khẩu ban đầu để kích hoạt thẻ','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V223','SIT223','P1','suon_se','chinh_thuc','Đổi mật khẩu ban đầu để kích hoạt thẻ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_01','V223','Nhân viên',1,'银行卡已经办好了，需要现场激活修改初始密码哦。','yín háng kǎ yǐ jīng bàn hǎo le， xū yào xiàn chǎng jī huó xiū gǎi chū shǐ mì mǎ ó。','Thẻ ngân hàng đã làm xong rồi, anh/chị cần kích hoạt và đổi mật khẩu ban đầu tại chỗ ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_02','V223','Nguyễn Minh',2,'好的，请问我怎么操作呢？我不太会用机器。','hǎo de， qǐng wèn wǒ zěn me cāo zuò ne？ wǒ bù tài huì yòng jī qì。','Vâng, xin hỏi tôi phải thao tác như thế nào ạ? Tôi không rành dùng máy lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_03','V223','Nhân viên',3,'没关系，我一步步教你，先输入初始密码，再设置新密码。','méi guān xì， wǒ yí bù bù jiāo nǐ， xiān shū rù chū shǐ mì mǎ， zài shè zhì xīn mì mǎ。','Không sao đâu, tôi sẽ hướng dẫn từng bước, đầu tiên nhập mật khẩu ban đầu, sau đó đặt mật khẩu mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_04','V223','Nguyễn Minh',4,'好，我设置好了，这样就激活成功了吧？','hǎo， wǒ shè zhì hǎo le， zhè yàng jiù jī huó chéng gōng le ba？','Vâng, tôi đặt xong rồi, như vậy là kích hoạt thành công rồi phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_05','V223','Nhân viên',5,'对的，现在可以正常存取款、扫码支付了。','duì de， xiàn zài kě yǐ zhèng cháng cún qǔ kuǎn、 sǎo mǎ zhī fù le。','Đúng vậy, giờ anh/chị có thể gửi rút tiền, quét mã thanh toán bình thường rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_06','V223','Nguyễn Minh',6,'太好了，非常感谢您的帮助！','tài hǎo le， fēi cháng gǎn xiè nín de bāng zhù！','Tuyệt quá, cảm ơn anh/chị rất nhiều vì đã giúp đỡ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT224','S5','Đăng ký thanh toán điện tử, xác thực danh tính','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V224','SIT224','P1','suon_se','tuy_y','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_01','V224','Nguyễn Minh',1,'小杨，我想注册微信支付，还要实名认证对吧？','xiǎo yáng， wǒ xiǎng zhù cè wēi xìn zhī fù， hái yào shí míng rèn zhèng duì ba？','Tiểu Dương, mình muốn đăng ký WeChat Pay, còn phải xác thực danh tính thật đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_02','V224','Bạn (Tiểu Dương)',2,'对呀，不认证没法扫码付钱、转账的。','duì ya， bù rèn zhèng méi fǎ sǎo mǎ fù qián、 zhuǎn zhàng de。','Đúng rồi, không xác thực thì không quét mã trả tiền hay chuyển khoản được đâu.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_03','V224','Nguyễn Minh',3,'那留学生用护照也能认证吗？我没有身份证呢。','nà liú xué shēng yòng hù zhào yě néng rèn zhèng ma？ wǒ méi yǒu shēn fèn zhèng ne。','Vậy du học sinh dùng hộ chiếu cũng xác thực được à? Mình đâu có chứng minh thư.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_04','V224','Bạn (Tiểu Dương)',4,'可以的！直接选择护照认证，按提示上传照片就行啦。','kě yǐ de！ zhí jiē xuǎn zé hù zhào rèn zhèng， àn tí shì shàng chuán zhào piān jiù xíng la。','Được chứ! Cứ chọn xác thực bằng hộ chiếu, làm theo hướng dẫn tải ảnh lên là xong ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_05','V224','Nguyễn Minh',5,'原来这么简单，我马上试试！','yuán lái zhè me jiǎn dān， wǒ mǎ shàng shì shì！','Hóa ra đơn giản vậy thôi à, để mình thử ngay đây!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_06','V224','Bạn (Tiểu Dương)',6,'弄不懂随时喊我，我教你哈。','nòng bù dǒng suí shí hǎn wǒ， wǒ jiāo nǐ hā。','Không hiểu gì thì cứ gọi mình, mình chỉ cho.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT225','S11','Thanh toán quét mã ở cửa hàng tiện lợi','Thanh toán nhanh bằng ví điện tử khi mua đồ','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V225','SIT225','P1','suon_se','tuy_y','Thanh toán nhanh bằng ví điện tử khi mua đồ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_01','V225','Nhân viên',1,'一共二十五元，你扫码支付就可以啦。','yī gòng èr shí wǔ yuán， nǐ sǎo mǎ zhī fù jiù kě yǐ la。','Tổng cộng hai mươi lăm tệ, bạn quét mã thanh toán là được nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_02','V225','Nguyễn Minh',2,'好的，我打开微信二维码，您扫我吧？','hǎo de， wǒ dǎ kāi wēi xìn èr wéi mǎ， nín sǎo wǒ ba？','Dạ được, em mở mã QR WeChat lên, anh/chị quét cho em nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_03','V225','Nhân viên',3,'可以的，或者你扫收银台的码也行哦。','kě yǐ de， huò zhě nǐ sǎo shōu yín tái de mǎ yě xíng ó。','Được đó, hoặc bạn quét mã ở quầy thu ngân cũng được nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_04','V225','Nguyễn Minh',4,'我扫好了，支付成功了，您看一下！','wǒ sǎo hǎo le， zhī fù chéng gōng le， nín kàn yī xià！','Em quét xong rồi, thanh toán thành công rồi, anh/chị xem thử nhé!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_05','V225','Nhân viên',5,'收到啦，没问题！东西拿好，慢走哈。','shōu dào la， méi wèn tí！ dōng xī ná hǎo， màn zǒu hā。','Nhận được rồi nha, không vấn đề gì! Cầm đồ cẩn thận, đi cẩn thận nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_06','V225','Nguyễn Minh',6,'谢谢！','xiè xiè！','Cảm ơn ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT226','S8','Báo danh văn phòng sinh viên quốc tế','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V226','SIT226','P1','suon_se','ban_chinh_thuc','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_01','V226','Nguyễn Minh',1,'老师您好，我是新生阮明，今天来国际学生办公室报到。','lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， jīn tiān lái guó jì xué shēng bàn gōng shì bào dào。','Chào thầy/cô, em là sinh viên mới Nguyễn Minh, hôm nay em đến văn phòng sinh viên quốc tế để báo danh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_02','V226','Cán bộ',2,'你好！麻烦提交一下你的护照、签证和录取通知书哦。','nǐ hǎo！ má fán tí jiāo yī xià nǐ de hù zhào、 qiān zhèng hé lù qǔ tōng zhī shū ó。','Chào em! Phiền em nộp hộ, chị hộ chiếu, visa và giấy báo nhập học của em nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_03','V226','Nguyễn Minh',3,'好的，这是我的全部材料，您查收一下。','hǎo de， zhè shì wǒ de quán bù cái liào， nín chá shōu yī xià。','Dạ vâng, đây là toàn bộ giấy tờ của em, thầy/cô kiểm tra giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_04','V226','Cán bộ',4,'材料齐全无误，这边帮你完成新生注册啦。','cái liào qí quán wú wù， zhè biān bāng nǐ wán chéng xīn shēng zhù cè la。','Giấy tờ đầy đủ, không có vấn đề gì, để chị giúp em hoàn tất đăng ký sinh viên mới nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_05','V226','Nguyễn Minh',5,'请问接下来还有其他报到流程吗？','qǐng wèn jiē xià lái hái yǒu qí tā bào dào liú chéng ma？','Dạ cho em hỏi sau đây còn quy trình báo danh nào khác không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_06','V226','Cán bộ',6,'基本完成了，后续选课、体检通知会统一发群里呢。','jī běn wán chéng le， hòu xù xuǎn kè、 tǐ jiǎn tōng zhī huì tǒng yī fā qún lǐ ne。','Về cơ bản là xong rồi, sau này thông báo chọn môn, khám sức khỏe sẽ được gửi chung trong nhóm nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_07','V226','Nguyễn Minh',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy/cô ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT227','S8','Thiếu giấy tờ, xin nộp bổ sung','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V227','SIT227','P1','twist','ban_chinh_thuc','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','新生报到材料缺失，多数学校允许限期补交，态度诚恳致歉即可，无需过度紧张；线上截图、电子版打印件大多不具备归档效力，必须纸质复印件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_01','V227','老师',1,'同学你先坐，我们核对一下新生报到需要提交的全套材料。','tóng xué nǐ xiān zuò， wǒ men hé duì yī xià xīn shēng bào dào xū yào tí jiāo de quán tào cái liào。','Em ngồi xuống trước đi, chúng ta cùng kiểm tra lại toàn bộ hồ sơ cần nộp cho việc báo danh sinh viên mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_02','V227','阮明',2,'好的老师，我把手里的文件都拿出来给您核对。','hǎo de lǎo shī， wǒ bǎ shǒu lǐ de wén jiàn dōu ná chū lái gěi nín hé duì。','Dạ vâng thầy/cô, em lấy hết giấy tờ đang có ra để thầy/cô kiểm tra ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_03','V227','老师',3,'毕业证复印件、签证页、体检表都齐了，还差一份疫苗接种证明，你带过来了吗？','bì yè zhèng fù yìn jiàn、 qiān zhèng yè、 tǐ jiǎn biǎo dōu qí le， hái chà yī fèn yì miáo jiē zhǒng zhèng míng， nǐ dài guò lái le ma？','Bản sao bằng tốt nghiệp, trang visa, giấy khám sức khỏe đều đủ cả rồi, chỉ còn thiếu giấy chứng nhận tiêm vaccine, em có mang theo không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_04','V227','阮明',4,'不好意思老师，出门收拾行李的时候漏掉这份材料，我完全忘记带了，非常抱歉。','bù hǎo yì sī lǎo shī， chū mén shōu shí xíng lǐ de shí hòu lòu diào zhè fèn cái liào， wǒ wán quán wàng jì dài le， fēi cháng bào qiàn。','Em xin lỗi thầy/cô, lúc thu dọn hành lý em đã bỏ sót giấy này, em hoàn toàn quên mang theo, em thực sự rất xin lỗi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_05','V227','老师',5,'没事的，不用紧张，很多新生都会出现材料遗漏的情况。','méi shì de， bù yòng jǐn zhāng， hěn duō xīn shēng dōu huì chū xiàn cái liào yí lòu de qíng kuàng。','Không sao đâu, em đừng căng thẳng, rất nhiều sinh viên mới cũng bị thiếu sót giấy tờ như vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_06','V227','阮明',6,'我心里特别着急，怕耽误今天的新生登记流程，影响后续选课住宿。','wǒ xīn lǐ tè bié zháo jí， pà dān wù jīn tiān de xīn shēng dēng jì liú chéng， yǐng xiǎng hòu xù xuǎn kè zhù sù。','Em thấy rất lo lắng trong lòng, sợ làm chậm trễ quy trình đăng ký sinh viên mới hôm nay, ảnh hưởng đến việc chọn môn và chỗ ở sau này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_07','V227','老师',7,'我先跟你说明学校的规定，所有材料必须完整归档，不能长期缺件。','wǒ xiān gēn nǐ shuō míng xué xiào de guī dìng， suǒ yǒu cái liào bì xū wán zhěng guī dàng， bù néng cháng qī quē jiàn。','Trước tiên chị nói rõ quy định của trường cho em biết, tất cả giấy tờ đều phải nộp đầy đủ, không được để thiếu lâu dài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_08','V227','阮明',8,'那请问我明天补交可以吗？明天补交完整不会影响我的新生报到手续吧？','nà qǐng wèn wǒ míng tiān bǔ jiāo kě yǐ ma？ míng tiān bǔ jiāo wán zhěng bú huì yǐng xiǎng wǒ de xīn shēng bào dào shǒu xù ba？','Vậy cho em hỏi ngày mai em nộp bổ sung có được không ạ? Ngày mai nộp đầy đủ thì có ảnh hưởng đến thủ tục báo danh sinh viên mới của em không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_09','V227','老师',9,'正常截止时间是今天下午五点，严格来说逾期不予受理，不过可以给你特殊放宽一天。','zhèng cháng jié zhǐ shí jiān shì jīn tiān xià wǔ wǔ diǎn， yán gé lái shuō yú qī bù yǔ shòu lǐ， bù guò kě yǐ gěi nǐ tè shū fàng kuān yī tiān。','Thời hạn bình thường là năm giờ chiều nay, nói nghiêm túc thì quá hạn sẽ không được tiếp nhận, nhưng chị có thể linh động cho em thêm một ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_10','V227','阮明',10,'太感谢老师愿意通融，我明天一早就回家找出证明，复印完整送过来。','tài gǎn xiè lǎo shī yuàn yì tōng róng， wǒ míng tiān yī zǎo jiù huí jiā zhǎo chū zhèng míng， fù yìn wán zhěng sòng guò lái。','Em cảm ơn thầy/cô rất nhiều vì đã thông cảm, sáng mai em sẽ về nhà ngay để tìm giấy chứng nhận, photo đầy đủ rồi mang đến.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_11','V227','老师',11,'记住一定要带纸质原件复印件，照片截图打印出来是不被认可的。','jì zhù yí dìng yào dài zhǐ zhì yuán jiàn fù yìn jiàn， zhào piān jié tú dǎ yìn chū lái shì bù bèi rèn kě de。','Nhớ là phải mang bản gốc giấy in và bản photo nhé, ảnh chụp màn hình in ra thì không được chấp nhận đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_12','V227','阮明',12,'我记下这条要求了，明天一定准备规范的纸质文件。','wǒ jì xià zhè tiáo yāo qiú le， míng tiān yí dìng zhǔn bèi guī fàn de zhǐ zhì wén jiàn。','Em ghi nhớ yêu cầu này rồi ạ, ngày mai em nhất định sẽ chuẩn bị giấy tờ đúng quy cách.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_13','V227','老师',13,'行，我先把你现有材料临时存档，等你补齐再统一录入系统。','xíng， wǒ xiān bǎ nǐ xiàn yǒu cái liào lín shí cún dàng， děng nǐ bǔ qí zài tǒng yī lù rù xì tǒng。','Được, để chị lưu tạm hồ sơ hiện có của em trước, đợi em bổ sung đầy đủ rồi sẽ nhập chung vào hệ thống.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_14','V227','阮明',14,'给老师增添额外工作量实在不好意思，我明天准时送来！','gěi lǎo shī zēng tiān é wài gōng zuò liàng shí zài bù hǎo yì sī， wǒ míng tiān zhǔn shí sòng lái！','Em làm phiền thầy/cô thêm việc thế này thật sự áy náy quá, ngày mai em sẽ mang đến đúng giờ ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT228','S9','Chọn môn, lớp đã đầy phải đổi lớp','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào thầy/cô, môn tiếng Hán em muốn chọn đã báo đầy chỗ rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp hot này số lượng chỗ đã được đăng ký hết rồi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể chuyển sang lớp ở khung giờ khác không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học giống nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em cứ đổi sang lớp này luôn được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em thao tác trực tiếp trên hệ thống là được, không cần nộp đơn thêm gì cả.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, em rất vui được làm học trò của cô ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường, em thích nghi với cuộc sống ở đây chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang dần quen ạ, em muốn hỏi thăm, việc chọn môn của chuyên ngành mình có trọng tâm gì không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì em có thể chọn những môn liên quan đến thương mại quốc tế nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Dạ vâng, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải là được, không cần chọn quá nhiều môn, tránh áp lực quá lớn nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã hướng dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Em ơi, lại đây chụp ảnh làm thẻ sinh viên nào.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Dạ vâng, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em chưa rõ lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản lắm, không đội mũ, không đeo kính râm, để lộ trán ra là được nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Dạ, em chỉnh lại một chút, vậy được chưa ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Cười tươi lên, nhìn vào ống kính, xong ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là có thể làm thẻ sinh viên luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng vậy, ảnh sẽ được nhập vào hệ thống, một tuần sau là em lấy thẻ được rồi nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào thầy/cô, em là sinh viên mới, em muốn làm thẻ mượn sách thư viện ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em xuất trình thẻ sinh viên là làm miễn phí được ngay nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Dạ đây ạ, làm xong rồi thì mỗi lần em được mượn mấy cuốn sách ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Sinh viên quốc tế mỗi lần được mượn mười cuốn, thời hạn mượn là ba mươi ngày nhé.','AM04');
